const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cars=[],images=[],editId=null,deleteId=null,uploading=false,storageMode='local',featuresEditor;
async function api(path,options={}){const response=await fetch('/api/'+path,{...options,headers:options.body instanceof ArrayBuffer?{}:{'Content-Type':'application/json',...options.headers}});const data=await response.json();if(!response.ok){if(response.status===401&&path!=='admin/login')showLogin();throw Error(data.error||'Não foi possível concluir a operação.')}return data}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function showLogin(){$('#login-section').hidden=false;$('#dashboard').hidden=true;$('#logout').hidden=true}
async function loadDashboard(){const session=await api('admin/session');storageMode=session.storage;cars=await api('vehicles');const settings=await api('settings');if(!featuresEditor){const {initFeatures}=await import('/admin-features.js');featuresEditor=await initFeatures(api);}$('#login-section').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;$('#storage-status').textContent=`Banco de dados: ${session.database||'Local'}. Fotos: ${session.storage}.`;
$('#bucket-description').textContent=session.bucketConfigured?(session.storage==='Vercel Blob'?'Vercel Blob conectado. As fotos são enviadas diretamente ao armazenamento, com autorização do painel.':'Armazenamento S3 compatível conectado.'):'Modo local ativo: fotos salvas no servidor. A integração Vercel Blob está preparada; configure as variáveis de ambiente para conectar seu bucket.';
$('#settings-form').elements.gtmId.value=settings.gtmId;$('#settings-form').elements.metaPixelId.value=settings.metaPixelId;render()}
function render(){const term=$('#admin-search').value.toLowerCase();$('#inventory-count').textContent=cars.length;const list=cars.filter(c=>`${c.brand} ${c.name} ${c.year}`.toLowerCase().includes(term));$('#admin-list').innerHTML=list.map(c=>`<article class="admin-row"><img src="${esc(c.images[0])}" alt="${esc(c.name)}"><div class="row-info"><h3>${esc(c.brand+' '+c.name)}</h3><p>${c.year} · ${esc(c.version)} · ${new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(c.price)}</p></div><div class="row-actions"><button class="button outline" data-edit="${esc(c.id)}">Editar</button> <button class="button danger" data-delete="${esc(c.id)}">Remover</button></div></article>`).join('')||'<p>Nenhum veículo encontrado.</p>'}
$('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('#login-error').textContent='';try{await api('admin/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});$('#password').value='';await loadDashboard()}catch(err){$('#login-error').textContent=err.message}finally{button.disabled=false}};
$('#logout').onclick=async()=>{try{await api('admin/logout',{method:'POST',body:'{}'});showLogin()}catch(err){toast(err.message)}};
$('#admin-search').oninput=render;
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.classList.toggle('selected',t===b));$('#inventory-panel').hidden=b.dataset.tab!=='inventory';$('#settings-panel').hidden=b.dataset.tab!=='settings';$('#import-panel').hidden=b.dataset.tab!=='import';$('#leads-panel').hidden=b.dataset.tab!=='leads';if(b.dataset.tab==='leads')window.gasparLeads?.open();if(b.dataset.tab==='import')window.gasparImporter?.open()});
function openEditor(c){editId=c?.id||null;images=[...(c?.images||[])];$('#vehicle-form').reset();featuresEditor.set(c?.features||[]);$('#editor-error').textContent='';$('#upload-status').textContent='';$('#editor-title').textContent=c?'Editar veículo':'Adicionar veículo';if(c){for(const [key,value]of Object.entries(c)){const field=$('#vehicle-form').elements.namedItem(key);if(field&&key!=='id')field.value=value;}}else{$('#vehicle-form').elements.year.value=new Date().getFullYear();$('#vehicle-form').elements.km.value=0}renderPhotos();$('#editor').showModal()}
$('#new-vehicle').onclick=()=>openEditor();
function closeEditor(){if(uploading){toast('Aguarde o upload terminar.');return}$('#editor').close()}
$('#close-editor').onclick=closeEditor;$('#cancel-editor').onclick=closeEditor;
$('#editor').addEventListener('cancel',e=>{if(uploading)e.preventDefault()});
$('#admin-list').onclick=e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit)openEditor(cars.find(c=>c.id===edit.dataset.edit));if(del){deleteId=del.dataset.delete;const c=cars.find(c=>c.id===deleteId);$('#delete-name').textContent=c.brand+' '+c.name+' '+c.year;$('#delete-error').textContent='';$('#delete-dialog').showModal()}};
$('#cancel-delete').onclick=()=>$('#delete-dialog').close();
$('#confirm-delete').onclick=async()=>{const button=$('#confirm-delete');button.disabled=true;try{await api('admin/vehicles/'+deleteId,{method:'DELETE',body:'{}'});cars=cars.filter(c=>c.id!==deleteId);render();$('#delete-dialog').close();toast('Veículo removido do estoque.')}catch(err){$('#delete-error').textContent=err.message}finally{button.disabled=false}};
function renderPhotos(){$('#photo-list').innerHTML=images.map((url,i)=>`<div class="photo-item"><img src="${esc(url)}" alt="Foto ${i+1}"><div><button type="button" data-move="${i}" aria-label="Mover foto ${i+1} para a esquerda" ${i===0?'disabled':''}>←</button><button type="button" data-remove="${i}" aria-label="Remover foto ${i+1}">×</button></div></div>`).join('')}
$('#photo-list').onclick=e=>{const remove=e.target.closest('[data-remove]'),move=e.target.closest('[data-move]');if(remove)images.splice(Number(remove.dataset.remove),1);if(move){const i=Number(move.dataset.move);if(i>0)[images[i-1],images[i]]=[images[i],images[i-1]]}renderPhotos()};
$('#photo-input').onchange=async e=>{const files=Array.from(e.target.files);if(!files.length)return;if(images.length+files.length>20){toast('Limite de 20 fotos por veículo.');e.target.value='';return}uploading=true;$('#save-vehicle').disabled=true;$('#photo-input').disabled=true;let sent=0;try{for(const file of files){if(file.size>8*1024*1024)throw Error(`${file.name}: limite de 8 MB por foto.`);$('#upload-status').textContent=`Enviando ${sent+1} de ${files.length}…`;let result;if(storageMode==='Vercel Blob'){const {uploadPhoto}=await import('/blob-client.js');const blob=await uploadPhoto(file);result=await api('admin/blob-confirm',{method:'POST',body:JSON.stringify({url:blob.url})});}else{result=await api('admin/upload',{method:'POST',body:await file.arrayBuffer()})};images.push(result.url);sent++;renderPhotos()}$('#upload-status').textContent=`${sent} foto(s) enviada(s).`}catch(err){$('#upload-status').textContent=err.message}finally{uploading=false;$('#save-vehicle').disabled=false;$('#photo-input').disabled=false;e.target.value=''}};
$('#vehicle-form').onsubmit=async e=>{e.preventDefault();if(uploading)return;const form=e.target;$('#editor-error').textContent='';if(!images.length){$('#editor-error').textContent='Adicione pelo menos uma foto.';return}const data=Object.fromEntries(new FormData(form));for(const key of ['year','price','km'])data[key]=Number(data[key]);data.images=images;data.features=featuresEditor.values();$('#save-vehicle').disabled=true;try{await api('admin/vehicles'+(editId?'/'+editId:''),{method:editId?'PUT':'POST',body:JSON.stringify(data)});cars=await api('vehicles');render();$('#editor').close();toast(editId?'Veículo atualizado.':'Veículo adicionado ao estoque.')}catch(err){$('#editor-error').textContent=err.message}finally{$('#save-vehicle').disabled=false}};
$('#settings-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('#settings-result').textContent='';try{const data=Object.fromEntries(new FormData(e.target));for(const key of Object.keys(data))data[key]=data[key].trim();await api('admin/settings',{method:'PUT',body:JSON.stringify(data)});$('#settings-result').textContent='Integrações salvas. Os IDs serão usados após o consentimento do visitante.'}catch(err){$('#settings-result').textContent=err.message}finally{button.disabled=false}};
loadDashboard().catch(()=>showLogin());
